// =============================================
// Спрайты — картинки персонажей
// =============================================
//
// Каждый кадр — это «пиксельная карта»: массив строк.
// Одна строка = один ряд пикселей, один символ = один пиксель.
//
// ЛЕГЕНДА СИМВОЛОВ (палитра Sweetie 16):
//   .  прозрачный пиксель
//   0  #1a1c2c  почти чёрный (контур, волосы Филиппа, борода Сани)
//   1  #5d275d  тёмно-фиолетовый (каштановые волосы Леры)
//   2  #b13e53  тёмно-красный (шлёпанцы Филиппа, пряди волос Леры, губы)
//   3  #ef7d57  оранжевый (тень кожи)
//   4  #ffcd75  жёлтый (кожа)
//   5  #a7f070  салатовый
//   6  #38b764  зелёный (кепка Сани)
//   7  #257179  тёмно-бирюзовый (кофта Сани, шлёпанцы Леры)
//   8  #29366f  тёмно-синий (тень шорт, тень платья Леры)
//   9  #3b5dc9  синий (шорты Филиппа, платье Леры)
//   a  #41a6f6  голубой
//   b  #73eff7  светло-голубой
//   c  #f4f4f4  белый (майка)
//   d  #94b0c2  светло-серый (тень майки)
//   e  #566c86  серый
//   f  #333c57  тёмно-серый (блик на волосах и бороде)

const PALETTE = {
  '0': '#1a1c2c', '1': '#5d275d', '2': '#b13e53', '3': '#ef7d57',
  '4': '#ffcd75', '5': '#a7f070', '6': '#38b764', '7': '#257179',
  '8': '#29366f', '9': '#3b5dc9', 'a': '#41a6f6', 'b': '#73eff7',
  'c': '#f4f4f4', 'd': '#94b0c2', 'e': '#566c86', 'f': '#333c57',
};

// =============================================
// ФИЛИПП, 16x24. Смотрит ВПРАВО.
// Кадр собираем из трёх частей: голова + туловище + ноги.
// =============================================

// Голова (9 рядов). Тёмные волосы — только пятно на затылке (столбцы 6–7),
// а вся макушка и лоб спереди — голая кожа. Так видно залысину и высокий лоб.
const F_HEAD = [
  '......000000....',
  '.....00044440...', // макушка: сзади волосы, спереди кожа
  '.....0f044440...', // f — блик на волосах
  '.....00444440...', // лоб
  '.....00344040...', // 3 — ухо, 0 справа — глаз
  '.....043444440..', // нос торчит вперёд
  '.....04444430...', // 3 — рот
  '......0444440...', // подбородок
  '.......03330....', // шея
];

// Туловище (10 рядов): майка, рука, шорты.
// Пузо выпирает вперёд (вправо) на 2 пикселя, а спина ровная —
// левый край идёт прямой линией до самых ног (плоский таз).
const F_BODY = [
  '.....04cccc40...', // плечи
  '.....0c4cccc0...', // 4 — рука вдоль тела
  '.....0c4cccc0...',
  '.....0c4ccccc0..', // пузо начинается
  '.....0c4cccccd0.', // самое пузо (d — тень)
  '.....0c4cccccd0.',
  '.....0c4cccdd0..', // низ пуза в тени, нависает над шортами
  '.....09999990...', // шорты
  '.....08999990...',
  '.....09999990...',
];

// Вдох: пузо выпирает на 1 пиксель больше
const F_BODY_BREATH = [
  '.....04cccc40...',
  '.....0c4cccc0...',
  '.....0c4cccc0...',
  '.....0c4cccccd0.',
  '.....0c4ccccccd0',
  '.....0c4ccccccd0',
  '.....0c4ccccdd0.',
  '.....09999990...',
  '.....08999990...',
  '.....09999990...',
];

