// Прыжок: колени поджаты
const F_LEGS_TUCK = [
  '.....09999990...',
  '......0444440...',
  '.....04400440...',
  '.....0220.0220..',
  '................',
];

// Падение: ноги свисают
const F_LEGS_FALL = [
  '.....09900990...',
  '.....04400440...',
  '.....04400440...',
  '.....0440.04440.',
  '.....0220.0220..',
];

// Склеиваем части в один кадр 16x24
function joinParts(head, body, legs) {
  return head.concat(body, legs);
}

// Филипп с молотком (для сценки поражения). Кадр 1 — замах, кадр 2 — удар.
// Молоток: головка e (серая) в контуре 0, ручка 3. Левая рука спрятана — работает правая.
const F_HAMMER_UP = [
  '......000000.000',
  '.....00044440ee0', // головка молотка над головой
  '.....0f044440ee0',
  '.....00444440000',
  '.....00344040.3.', // ручка
  '.....0434444403.',
  '.....04444430440', // кисть держит ручку
  '......044444040.', // рука поднята
  '.......033304...',
  '.....0ccccc440..',
  '.....0cccccc0...',
  '.....0cccccc0...',
  '.....0ccccccc0..',
  '.....0cccccccd0.',
  '.....0cccccccd0.',
  '.....0cccccdd0..',
].concat(F_BODY.slice(7), F_LEGS_STAND);  // шорты и ноги как у стоящего

const F_HAMMER_DOWN = F_HEAD.concat([
  '.....04cccc40...',
  '.....0ccccc440.0', // рука вытянута вперёд
  '.....0cccccc044e', // кисть и головка молотка справа
  '.....0ccccccc0.e',
  '.....0cccccccd00',
  '.....0cccccccd0.',
  '.....0cccccdd0..',
], F_BODY.slice(7), F_LEGS_STAND);

// Сами анимации Филиппа.
// frames — список кадров, speed — сколько шагов игры держится один кадр.
const FILIPP_ANIMS = {
  idle: {
    name: 'Стоит',
    speed: 40,
    frames: [
      joinParts(F_HEAD, F_BODY, F_LEGS_STAND),
      joinParts(F_HEAD, F_BODY_BREATH, F_LEGS_STAND),
    ],
  },
  run: {
    name: 'Бег',
    speed: 7,
    frames: [
      joinParts(F_HEAD, F_BODY_ARM_FWD, F_LEGS_STRIDE),
      joinParts(F_HEAD, F_BODY, F_LEGS_PASS),
      joinParts(F_HEAD, F_BODY_ARM_BACK, F_LEGS_STRIDE),
      joinParts(F_HEAD, F_BODY, F_LEGS_PASS),
    ],
  },
  jump: {
    name: 'Прыжок вверх',
    speed: 60,
    frames: [joinParts(F_HEAD, F_BODY_ARM_FWD, F_LEGS_TUCK)],
  },
  fall: {
    name: 'Падение',
    speed: 60,
    frames: [joinParts(F_HEAD, F_BODY_ARM_BACK, F_LEGS_FALL)],
  },
  // Стучит молотком. Кадр 2 (номер 1) — удар: в этот момент игра пишет «ТУК-ТУК» и стучит.
  hammer: {
    name: 'Молоток',
    speed: 15,
    frames: [F_HAMMER_UP, F_HAMMER_DOWN],
  },
};

