// Второй кадр «дыхания»: верх тела опускается на 1 пиксель.
// Добавляем пустой ряд сверху и убираем один ряд из середины (ряд 13).
function breathDown(rows, cutRow) {
  const empty = '.'.repeat(rows[0].length);
  return [empty].concat(rows.slice(0, cutRow), rows.slice(cutRow + 1));
}

const LERA_ANIMS = {
  idle: {
    name: 'Стоит',
    speed: 40,
    frames: [LERA_STAND, breathDown(LERA_STAND, 13)],
  },
};

