// =============================================
// ВАСЯ И НАСТЯ (близнецы, 5 лет), 10x14. Смотрят ВПРАВО.
// Кудрявые светлые волосы (4, кудряшки 3, блик c). Вася — красное платье (2, тень 1),
// Настя — голубое (a, тень 9). Сидят — играют с игрушкой.
// =============================================
function twinAnims(p) {
  return {
    stand: { name: 'Стоит', speed: 60, frames: [p.stand] },
    run:   { name: 'Бежит', speed: 7, frames: [p.run1, p.run2] },
    jump:  { name: 'Прыгает', speed: 60, frames: [p.jump] },
    sit:   { name: 'Сидит и играет', speed: 60, frames: [p.sit] },
  };
}
