// Рисует игрушку 8x8
function drawToy(g, kind, x, y) {
  if (!drawToy.images) drawToy.images = {};
  if (!drawToy.images[kind]) drawToy.images[kind] = makeFrame(TOY_MAPS[kind], 8, 8, 'Игрушка ' + kind);
  g.drawImage(drawToy.images[kind], x, y);
}

// Сердечко 5x5 для шкалы босса. on = ещё не погасло
function drawHeart(g, x, y, on) {
  g.fillStyle = on ? '#b13e53' : '#333c57';
  g.fillRect(x, y, 2, 2); g.fillRect(x + 3, y, 2, 2);
  g.fillRect(x, y + 1, 5, 2);
  g.fillRect(x + 1, y + 3, 3, 1);
  g.fillRect(x + 2, y + 4, 1, 1);
}

// Тень падающей игрушки на земле: чем ближе падение, тем шире
function drawToyShadow(g, cx, y, p) {
  const w = 3 + Math.round(p * 6);
  g.fillStyle = '#1a1c2c';
  g.fillRect(cx - w, y - 1, w * 2, 2);
}

// =============================================
// Превращаем пиксельные карты в картинки
// =============================================

// Рисует одну пиксельную карту на маленьком холсте.
// Делаем это один раз при запуске, а потом просто копируем готовую картинку.
function makeFrame(rows, w, h, label) {
  const c = document.createElement('canvas');
  c.width = w;
  c.height = h;
  const g = c.getContext('2d');
  if (rows.length !== h) console.warn(label + ': рядов ' + rows.length + ', а нужно ' + h);
  rows.forEach((row, y) => {
    if (row.length !== w) console.warn(label + ', ряд ' + y + ': длина ' + row.length + ', а нужно ' + w);
    for (let x = 0; x < row.length; x++) {
      const ch = row[x];
      if (ch === '.') continue;            // прозрачный пиксель
      const color = PALETTE[ch];
      if (!color) { console.warn(label + ': неизвестный символ «' + ch + '»'); continue; }
      g.fillStyle = color;
      g.fillRect(x, y, 1, 1);
    }
  });
  return c;
}

// Готовим все анимации персонажа
function buildCharacter(name, w, h, anims) {
  const result = { name: name, w: w, h: h, anims: {} };
  for (const key in anims) {
    const a = anims[key];
    const frames = padEdges(a.frames);
    result.anims[key] = {
      name: a.name,
      speed: a.speed,
      frames: frames.map((rows, i) => makeFrame(rows, rows[0].length, rows.length, name + ' ' + key + ' #' + i)),
    };
  }
  return result;
}

// Рисунок упёрся в верхний, левый или правый край кадра (там цветной пиксель, а не контур) —
// иначе голова, хвост или кружка будут обрезаны. Тогда расширяем кадр на пиксель с этой стороны
// и дорисовываем контур 0 на новом крае. Все кадры одной анимации расширяем одинаково,
// чтобы картинка не дёргалась. Низ не трогаем: ноги стоят на нижнем ряду.
function padEdges(frames) {
  const colored = (ch) => ch !== '.' && ch !== '0';
  const need = { top: false, left: false, right: false };
  for (const rows of frames) {
    if ([...rows[0]].some(colored)) need.top = true;
    for (const r of rows) {
      if (colored(r[0])) need.left = true;
      if (colored(r[r.length - 1])) need.right = true;
    }
  }
  if (!need.top && !need.left && !need.right) return frames;
  return frames.map((rows) => {
    const w = rows[0].length;
    let out = rows.map((r) => (need.left ? '.' : '') + r + (need.right ? '.' : ''));
    if (need.top) out = ['.'.repeat(out[0].length)].concat(out);
    const dx = need.left ? 1 : 0, dy = need.top ? 1 : 0;
    const old = (x, y) => (y >= 0 && y < rows.length && x >= 0 && x < w ? rows[y][x] : '.');
    return out.map((r, y) => [...r].map((ch, x) => {
      const isNew = (need.top && y === 0) || (need.left && x === 0) || (need.right && x === r.length - 1);
      if (!isNew) return ch;
      const ox = x - dx, oy = y - dy;            // где эта клетка была бы в старом кадре
      const near = [[1, 0], [-1, 0], [0, 1], [0, -1]].some(([ax, ay]) => colored(old(ox + ax, oy + ay)));
      return near ? '0' : '.';
    }).join(''));
  });
}

