// Облако дыма (Титя выдыхает «ПФФ»): сеточкой, чем меньше density (0–1), тем реже точки — тает
function drawSmokeCloud(g, cx, cy, r, density, t) {
  const ry = Math.round(r * 0.7);
  for (let y = -ry; y <= ry; y++) {
    for (let x = -r; x <= r; x++) {
      const d = (x * x) / (r * r) + (y * y) / (ry * ry);
      if (d > 1) continue;
      const n = (x * 7 + y * 13 + Math.floor(t / 6)) & 7;   // «шевелится»
      if (n >= density * 5) continue;                // облако полупрозрачное: сквозь него видно
      g.fillStyle = d < 0.4 ? '#94b0c2' : (d < 0.75 ? '#566c86' : '#5d275d');
      g.fillRect(cx + x, cy + y, 1, 1);
    }
  }
}

