// Анимации друга из кадров: idle (стоит), walk, sit, sitBeer, sitJoy, cheers
function friendAnims(P) {
  return {
    idle:    { name: 'Стоит', speed: 60, frames: [P.STAND] },
    walk:    { name: 'Идёт', speed: 10, frames: [P.WALK1, P.WALK2] },
    sit:     { name: 'Сидит', speed: 60, frames: [P.SIT] },
    sitBeer: { name: 'Сидит с пивом', speed: 60, frames: [P.SITBEER] },
    sitJoy:  { name: 'Сидит с джойстиком', speed: 60, frames: [P.SITJOY] },
    cheers:  { name: 'Чокается', speed: 60, frames: [P.CHEERS] },
  };
}
