// ---------- ФИНАЛ: ФОНЫ ----------
// Гирлянда: провод провисает между точками, лампочки разных цветов мигают по очереди
function drawGarland(g, x0, x1, y, sag, t) {
  const cols = ['#b13e53', '#ffcd75', '#38b764', '#41a6f6', '#ef7d57'];
  for (let x = x0; x <= x1; x++) {
    const k = (x - x0) / (x1 - x0);
    const yy = y + Math.round(Math.sin(k * Math.PI) * sag);
    g.fillStyle = '#1a1c2c';
    g.fillRect(x, yy, 1, 1);
    if ((x - x0) % 10 === 5) {
      const i = Math.floor((x - x0) / 10);
      g.fillStyle = (i + Math.floor(t / 20)) % 4 === 0 ? '#566c86' : cols[i % cols.length];   // одна из четырёх «отдыхает»
      g.fillRect(x - 1, yy + 1, 3, 3);
    }
  }
}

// Мангал с шашлыком: угли светятся, дымок поднимается
function drawMangal(g, x, y, t) {
  g.fillStyle = '#333c57';
  g.fillRect(x, y, 30, 8);                           // короб
  g.fillRect(x + 2, y + 8, 2, 12);                   // ножки
  g.fillRect(x + 26, y + 8, 2, 12);
  for (let i = 0; i < 26; i += 3) {                  // угли
    g.fillStyle = (i + Math.floor(t / 8)) % 4 === 0 ? '#ffcd75' : ((i + Math.floor(t / 12)) % 3 ? '#b13e53' : '#ef7d57');
    g.fillRect(x + 2 + i, y + 1, 2, 2);
  }
  for (const sx of [5, 13, 21]) {                    // шампуры с мясом
    g.fillStyle = '#94b0c2';
    g.fillRect(x + sx - 2, y - 2, 14, 1);
    g.fillStyle = '#b13e53';
    g.fillRect(x + sx, y - 4, 3, 3);
    g.fillRect(x + sx + 5, y - 4, 3, 3);
    g.fillStyle = '#5d275d';
    g.fillRect(x + sx + 1, y - 2, 1, 1);
  }
  g.fillStyle = '#94b0c2';                           // дымок
  for (let i = 0; i < 4; i++) {
    const k = (t / 3 + i * 10) % 40;
    g.fillRect(x + 12 + Math.round(Math.sin((t + i * 30) / 15) * 3), y - 6 - k, 2, 2);
  }
}

// Сцена 1: ночной двор дачи Сани — гирлянда, мангал, стол с пивом и шашлыком
BACKGROUNDS.dachaYard = function (g, t) {
  t = t || 0;
  g.fillStyle = '#1a1c2c';
  g.fillRect(0, 0, 240, 136);
  g.fillStyle = '#f4f4f4';                           // звёзды
  for (const [sx, sy] of [[14, 6], [52, 12], [96, 4], [130, 10], [172, 6], [214, 14], [228, 3], [70, 26]]) g.fillRect(sx, sy, 1, 1);
  pixelCircle(g, 200, 18, 6, '#ffcd75');             // луна
  pixelCircle(g, 203, 16, 5, '#1a1c2c');
  g.fillStyle = '#566c86';                           // домик Сани справа, окно горит
  g.fillRect(176, 30, 64, 56);
  g.fillStyle = '#5d275d';
  for (let i = 0; i < 34; i++) g.fillRect(170 + i, 30 - Math.floor(i / 2), 70 - i * 2 + i, 1);
  g.fillStyle = '#ffcd75';
  g.fillRect(196, 44, 18, 14);
  g.fillStyle = '#ef7d57';
  g.fillRect(204, 44, 2, 14);
  g.fillStyle = '#333c57';                           // забор сзади
  for (let i = 0; i < 176; i += 6) g.fillRect(i, 44, 4, 30);
  g.fillRect(0, 50, 176, 2);
  g.fillRect(0, 64, 176, 2);
  g.fillStyle = '#257179';                           // трава
  g.fillRect(0, 74, 240, 62);
  g.fillStyle = '#38b764';
  for (let i = 3; i < 240; i += 11) g.fillRect(i, 76 + (i % 4), 1, 2);
  drawGarland(g, 0, 176, 18, 14, t);                 // гирлянда от столба до домика
  drawMangal(g, 8, 58, t);
  g.fillStyle = '#b13e53';                           // стол
  g.fillRect(84, 62, 72, 4);
  g.fillStyle = '#5d275d';
  g.fillRect(84, 66, 72, 2);
  g.fillRect(88, 68, 3, 18);
  g.fillRect(149, 68, 3, 18);
  g.fillStyle = '#f4f4f4';                           // тарелка шашлыка
  g.fillRect(110, 60, 16, 2);
  g.fillStyle = '#b13e53';
  g.fillRect(112, 57, 3, 3); g.fillRect(117, 58, 3, 2); g.fillRect(121, 57, 3, 3);
  g.fillStyle = '#38b764';                           // бутылки и кружки
  g.fillRect(96, 52, 3, 10); g.fillRect(97, 50, 1, 2);
  g.fillRect(140, 53, 3, 9); g.fillRect(141, 51, 1, 2);
  drawBeer(g, 130, 54, false);
  g.fillStyle = '#5d275d';                           // лавки по бокам стола
  g.fillRect(60, 74, 24, 3);
  g.fillRect(156, 74, 24, 3);
};

// Сцена 2: старая комната на даче — ковёр на стене, диван, ламповый телевизор с приставкой
function drawOldTv(g, x, y, t) {
  g.fillStyle = '#b13e53';                           // тумба
  g.fillRect(x - 4, y + 30, 46, 26);
  g.fillStyle = '#5d275d';
  g.fillRect(x - 2, y + 34, 20, 18); g.fillRect(x + 20, y + 34, 20, 18);
  g.fillStyle = '#333c57';                           // корпус телевизора
  g.fillRect(x, y, 38, 30);
  g.fillStyle = '#566c86';
  g.fillRect(x + 30, y + 4, 6, 22);
  g.fillStyle = '#94b0c2';
  g.fillRect(x + 32, y + 6, 2, 2); g.fillRect(x + 32, y + 10, 2, 2);   // ручки
  g.fillStyle = '#1a1c2c';                           // антенна «рога»
  g.fillRect(x + 14, y - 1, 2, 1);
  for (let i = 0; i < 8; i++) { g.fillRect(x + 14 - i, y - 2 - i, 1, 1); g.fillRect(x + 16 + i, y - 2 - i, 1, 1); }
  // Экран: пиксельная игра — человечек прыгает по платформам, небо мигает
  const sx = x + 3, sy = y + 3;
  g.fillStyle = Math.floor(t / 30) % 2 ? '#3b5dc9' : '#41a6f6';
  g.fillRect(sx, sy, 26, 24);
  g.fillStyle = '#38b764';
  g.fillRect(sx, sy + 20, 26, 4);
  g.fillRect(sx + 4 + (Math.floor(t / 40) % 3) * 6, sy + 12, 8, 2);
  g.fillStyle = '#ffcd75';                           // монетка
  if (Math.floor(t / 10) % 2) g.fillRect(sx + 20, sy + 6, 2, 2);
  g.fillStyle = '#b13e53';                           // герой
  const jump = Math.abs(Math.sin(t / 15)) * 6;
  g.fillRect(sx + 8 + (Math.floor(t / 6) % 10), sy + 16 - Math.round(jump), 3, 4);
  g.fillStyle = '#73eff7';                           // блик выпуклого экрана
  g.fillRect(sx + 1, sy + 1, 3, 1);
  // Приставка на тумбе и провода к джойстикам (без логотипов)
  g.fillStyle = '#566c86';
  g.fillRect(x + 4, y + 26, 20, 4);
  g.fillStyle = '#1a1c2c';
  g.fillRect(x + 6, y + 27, 6, 1);
  g.fillStyle = '#b13e53';
  g.fillRect(x + 20, y + 27, 1, 1);
}

BACKGROUNDS.dachaRoom = function (g, t) {
  t = t || 0;
  g.fillStyle = '#257179';                           // обои
  g.fillRect(0, 0, 240, 86);
  g.fillStyle = '#38b764';
  for (let y = 4; y < 80; y += 10) for (let x = (y % 20 ? 5 : 0); x < 240; x += 10) g.fillRect(x, y, 2, 2);
  // Ковёр на стене: красный с узором-ромбами и бахромой
  const kx = 16, ky = 8, kw = 100, kh = 46;
  g.fillStyle = '#b13e53';
  g.fillRect(kx, ky, kw, kh);
  g.fillStyle = '#5d275d';
  g.fillRect(kx + 3, ky + 3, kw - 6, kh - 6);
  g.fillStyle = '#b13e53';
  g.fillRect(kx + 6, ky + 6, kw - 12, kh - 12);
  for (let i = 0; i < 4; i++) {                      // ромбы
    const cx = kx + 18 + i * 21, cy = ky + kh / 2;
    for (let d = 0; d < 9; d++) {
      g.fillStyle = d % 3 === 0 ? '#ffcd75' : '#ef7d57';
      g.fillRect(cx - d, cy - 9 + d, 1, 1); g.fillRect(cx + d, cy - 9 + d, 1, 1);
      g.fillRect(cx - d, cy + 9 - d, 1, 1); g.fillRect(cx + d, cy + 9 - d, 1, 1);
    }
    g.fillStyle = '#ffcd75';
    g.fillRect(cx - 1, cy - 1, 3, 3);
  }
  g.fillStyle = '#ffcd75';                           // бахрома
  for (let x = kx; x < kx + kw; x += 3) g.fillRect(x, ky + kh, 1, 2);
  // Пол — доски
  g.fillStyle = '#b13e53';
  g.fillRect(0, 80, 240, 56);
  g.fillStyle = '#5d275d';
  for (let x = 0; x < 240; x += 16) g.fillRect(x, 80, 1, 56);
  // Диван: спинка, подушки, сиденье
  g.fillStyle = '#29366f';
  g.fillRect(10, 54, 132, 24);
  g.fillStyle = '#3b5dc9';
  for (let i = 0; i < 4; i++) g.fillRect(14 + i * 32, 56, 30, 12);
  g.fillStyle = '#29366f';
  g.fillRect(6, 62, 8, 20); g.fillRect(138, 62, 8, 20);   // подлокотники
  g.fillStyle = '#3b5dc9';
  g.fillRect(14, 70, 124, 6);
  g.fillStyle = '#1a1c2c';
  g.fillRect(14, 82, 4, 4); g.fillRect(134, 82, 4, 4);   // ножки
  drawOldTv(g, 184, 30, t);
  g.fillStyle = '#1a1c2c';                           // провода джойстиков по полу
  for (let x = 120; x < 190; x += 2) g.fillRect(x, 84 - Math.round(Math.sin(x / 9)), 1, 1);
  // Лампа под потолком
  g.fillStyle = '#1a1c2c';
  g.fillRect(160, 0, 1, 8);
  g.fillStyle = '#ffcd75';
  g.fillRect(156, 8, 9, 4);
};

// ---------- ФИНАЛ: ОБЛАЧКА-МЕЧТЫ ----------
// Облачко 72x44 над говорящим: (x, y) — левый верх, tailX/tailY — к чьей голове кружочки
function drawDreamBubble(g, x, y, kind, t, tailX, tailY) {
  // Кружочки от головы к облачку
  for (let i = 1; i <= 3; i++) {
    const k = i / 4;
    pixelCircle(g, Math.round(tailX + (x + 36 - tailX) * k), Math.round(tailY + (y + 44 - tailY) * k), 1 + i, '#f4f4f4');
  }
  // Пухлое облако
  g.fillStyle = '#f4f4f4';
  g.fillRect(x + 4, y + 2, 64, 40);
  for (const [cx, cy, r] of [[x + 6, y + 8, 6], [x + 18, y + 3, 6], [x + 36, y + 2, 7], [x + 54, y + 3, 6], [x + 66, y + 10, 6],
                             [x + 66, y + 32, 6], [x + 50, y + 41, 5], [x + 30, y + 42, 5], [x + 10, y + 38, 6], [x + 3, y + 22, 5]]) {
    pixelCircle(g, cx, cy, r, '#f4f4f4');
  }
  // Картинка внутри 60x34
  const px = x + 6, py = y + 5;
  g.save();
  g.beginPath();
  g.rect(px, py, 60, 34);
  g.clip();
  DREAMS[kind](g, px, py, t);
  g.restore();
  g.fillStyle = '#94b0c2';                           // рамка картинки
  g.fillRect(px, py - 1, 60, 1); g.fillRect(px, py + 34, 60, 1);
  g.fillRect(px - 1, py, 1, 34); g.fillRect(px + 60, py, 1, 34);
}

// Картинки мечт 60x34 (без реальных людей и логотипов)
const DREAMS = {
  // Саня: баскетбольная площадка, мяч влетает в кольцо
  sanya(g, x, y, t) {
    g.fillStyle = '#29366f'; g.fillRect(x, y, 60, 34);              // зал
    g.fillStyle = '#ef7d57'; g.fillRect(x, y + 24, 60, 10);         // паркет
    g.fillStyle = '#b13e53'; for (let i = 0; i < 60; i += 8) g.fillRect(x + i, y + 24, 1, 10);
    g.fillStyle = '#f4f4f4'; g.fillRect(x, y + 27, 60, 1);          // линия
    g.fillStyle = '#f4f4f4'; g.fillRect(x + 44, y + 4, 12, 9);      // щит
    g.fillStyle = '#b13e53'; g.fillRect(x + 48, y + 7, 5, 4);
    g.fillStyle = '#566c86'; g.fillRect(x + 54, y + 13, 2, 11);     // стойка
    g.fillStyle = '#ef7d57'; g.fillRect(x + 40, y + 13, 9, 1);      // кольцо
    g.fillStyle = '#f4f4f4'; for (let i = 0; i < 4; i++) g.fillRect(x + 41 + i * 2, y + 14 + (i % 2), 1, 4);   // сетка
    const k = (t % 60) / 60;                                        // мяч летит в кольцо
    const bx = x + 10 + k * 34, by = y + 20 - Math.sin(k * Math.PI) * 16 - (k > 0.85 ? (k - 0.85) * -40 : 0);
    pixelCircle(g, Math.round(bx), Math.round(by), 3, '#ef7d57');
    g.fillStyle = '#1a1c2c'; g.fillRect(Math.round(bx) - 3, Math.round(by), 7, 1);
    drawText(g, '2', x + 4, y + 3, '#ffcd75'); drawText(g, ':0', x + 9, y + 3, '#ffcd75');
  },
  // Глеб: средневековый лагерь под куполом-барьером
  gleb(g, x, y, t) {
    g.fillStyle = '#1a1c2c'; g.fillRect(x, y, 60, 34);
    g.fillStyle = '#333c57'; g.fillRect(x, y + 24, 60, 10);         // земля
    g.fillStyle = '#5d275d'; for (let i = 2; i < 58; i += 4) g.fillRect(x + i, y + 16, 3, 9);   // частокол
    g.fillStyle = '#1a1c2c'; for (let i = 2; i < 58; i += 4) g.fillRect(x + i + 1, y + 15, 1, 1);
    g.fillStyle = '#b13e53'; for (const tx of [10, 32]) for (let d = 0; d < 6; d++) g.fillRect(x + tx - d, y + 18 + d, 2 * d + 1, 1);   // шатры
    g.fillStyle = Math.floor(t / 6) % 2 ? '#ffcd75' : '#ef7d57'; g.fillRect(x + 46, y + 26, 3, 3);   // костёр
    // Купол-барьер: мерцающая голубая дуга сеточкой
    for (let a = 0; a <= 60; a++) {
      const yy = y + 30 - Math.round(Math.sqrt(Math.max(0, 900 - (a - 30) * (a - 30))) * 0.9);
      if ((a + Math.floor(t / 4)) % 3) { g.fillStyle = '#73eff7'; g.fillRect(x + a, yy, 1, 1); }
      if ((a + Math.floor(t / 4)) % 5 === 0) { g.fillStyle = '#41a6f6'; g.fillRect(x + a, yy + 1, 1, 1); }
    }
  },
  // Лёня: голая белая комната, перечёркнутый аккордеон
  lenya(g, x, y, t) {
    g.fillStyle = '#f4f4f4'; g.fillRect(x, y, 60, 34);
    g.fillStyle = '#94b0c2';                                        // углы комнаты
    g.fillRect(x + 10, y, 1, 26); g.fillRect(x + 50, y, 1, 26); g.fillRect(x + 10, y + 26, 41, 1);
    for (let i = 0; i < 10; i++) { g.fillRect(x + 10 - i, y + 26 + Math.floor(i * 0.8), 1, 1); g.fillRect(x + 50 + i, y + 26 + Math.floor(i * 0.8), 1, 1); }
    // аккордеон: клавиши, меха, кнопки
    g.fillStyle = '#f4f4f4'; g.fillRect(x + 20, y + 9, 5, 14);
    g.fillStyle = '#1a1c2c'; for (let j = 0; j < 14; j += 3) g.fillRect(x + 20, y + 9 + j, 5, 1);
    g.fillStyle = '#3b5dc9'; for (let i = 0; i < 6; i++) g.fillRect(x + 25 + i * 2, y + 9, 1, 14);
    g.fillStyle = '#29366f'; for (let i = 0; i < 6; i++) g.fillRect(x + 26 + i * 2, y + 10, 1, 12);
    g.fillStyle = '#b13e53'; g.fillRect(x + 37, y + 9, 5, 14);
    g.fillStyle = '#ffcd75'; for (let j = 11; j < 22; j += 3) g.fillRect(x + 39, y + j, 1, 1);
    // красный крест поверх
    g.fillStyle = '#b13e53';
    for (let i = 0; i < 24; i++) { g.fillRect(x + 18 + i, y + 5 + i, 2, 2); g.fillRect(x + 42 - i, y + 5 + i, 2, 2); }
  },
  // Мозг: тропический остров, пальмы, огни кабаре
  mozg(g, x, y, t) {
    g.fillStyle = '#5d275d'; g.fillRect(x, y, 60, 34);              // вечернее небо
    g.fillStyle = '#b13e53'; g.fillRect(x, y + 14, 60, 6);
    g.fillStyle = '#3b5dc9'; g.fillRect(x, y + 20, 60, 14);         // море
    g.fillStyle = '#41a6f6'; for (let i = (t >> 3) % 6; i < 60; i += 6) g.fillRect(x + i, y + 24 + (i % 3) * 3, 3, 1);
    g.fillStyle = '#ffcd75'; g.fillRect(x + 8, y + 22, 44, 5);      // песок острова
    g.fillRect(x + 12, y + 21, 36, 1);
    for (const [px, h] of [[12, 12], [46, 10]]) {                   // пальмы
      g.fillStyle = '#ef7d57'; for (let j = 0; j < h; j++) g.fillRect(x + px + (j > h / 2 ? 0 : 1), y + 21 - j, 1, 1);
      g.fillStyle = '#38b764';
      g.fillRect(x + px - 4, y + 21 - h, 9, 1); g.fillRect(x + px - 5, y + 22 - h, 2, 1); g.fillRect(x + px + 4, y + 22 - h, 2, 1);
      g.fillRect(x + px - 1, y + 20 - h, 3, 1);
    }
    g.fillStyle = '#29366f'; g.fillRect(x + 22, y + 14, 16, 8);     // сцена кабаре
    g.fillStyle = '#b13e53'; g.fillRect(x + 22, y + 13, 16, 2);
    const cols = ['#ffcd75', '#73eff7', '#a7f070', '#ef7d57'];
    for (let i = 0; i < 8; i++) { g.fillStyle = cols[(i + (t >> 4)) % 4]; g.fillRect(x + 22 + i * 2, y + 12, 1, 1); }   // огни
    g.fillStyle = (t >> 3) % 2 ? '#a7f070' : '#73eff7';             // перья и блёстки
    g.fillRect(x + 28, y + 16, 1, 3); g.fillRect(x + 31, y + 15, 1, 4); g.fillRect(x + 34, y + 16, 1, 3);
  },
  // Филипп: белый теплоход на закате, на палубе луч прожектора
  filipp(g, x, y, t) {
    const sky = ['#5d275d', '#b13e53', '#ef7d57', '#ffcd75'];
    for (let i = 0; i < 4; i++) { g.fillStyle = sky[i]; g.fillRect(x, y + i * 5, 60, 5); }
    pixelCircle(g, x + 44, y + 20, 5, '#ffcd75');                   // солнце садится
    g.fillStyle = '#29366f'; g.fillRect(x, y + 20, 60, 14);         // Волга
    g.fillStyle = '#ef7d57'; for (let j = 22; j < 34; j += 3) g.fillRect(x + 41 + (j % 2), y + j, 6, 1);   // дорожка от солнца
    const sx = x + 6 + Math.round(Math.sin(t / 40) * 2);
    g.fillStyle = '#f4f4f4'; g.fillRect(sx, y + 17, 34, 5);         // корпус
    g.fillRect(sx + 2, y + 22, 30, 1);
    g.fillStyle = '#b13e53'; g.fillRect(sx, y + 20, 34, 1);         // полоса
    g.fillStyle = '#f4f4f4'; g.fillRect(sx + 6, y + 12, 22, 5);     // палубы
    g.fillRect(sx + 10, y + 8, 14, 4);
    g.fillStyle = '#41a6f6'; for (let i = 0; i < 5; i++) g.fillRect(sx + 8 + i * 4, y + 14, 2, 1);   // окошки
    g.fillStyle = '#b13e53'; g.fillRect(sx + 20, y + 4, 3, 4);      // труба
    // Прожектор с палубы: луч сеточкой
    g.fillStyle = '#f4f4f4';
    for (let i = 0; i < 18; i++) for (let j = -Math.floor(i / 3); j <= Math.floor(i / 3); j++) {
      if ((i + j + (t >> 3)) % 2) g.fillRect(sx + 12 - j, y + 8 - i, 1, 1);
    }
  },
};

// Большой телефон: пришло сообщение. Вибрирует. from — кто пишет, text — что
function drawMessagePhone(g, cx, cy, from, text, t) {
  const sh = Math.floor(t / 2) % 2 && t < 60 ? 1 : 0;           // вибрирует первую секунду
  const x = cx - 40 + sh, y = cy - 30;
  g.fillStyle = '#1a1c2c';
  g.fillRect(x - 2, y - 2, 84, 64);
  g.fillStyle = '#333c57';
  g.fillRect(x, y, 80, 60);
  g.fillStyle = '#566c86';
  g.fillRect(x + 36, y + 2, 8, 1);                            // динамик
  g.fillStyle = '#f4f4f4';
  g.fillRect(x + 4, y + 6, 72, 48);                           // экран
  g.fillStyle = '#41a6f6';
  g.fillRect(x + 4, y + 6, 72, 9);
  drawText(g, from, x + 8, y + 7, '#f4f4f4');
  const lines = wrapText(text, 64);
  lines.forEach((ln, i) => drawText(g, ln, x + 8, y + 19 + i * 9, '#1a1c2c'));
  if (t > 30 && Math.floor(t / 20) % 2) { g.fillStyle = '#b13e53'; g.fillRect(x + 68, y + 8, 5, 5); }   // «новое»
}
